   235  // Maintainers note htsFile cannot be an incomplete struct because some of its
   236  // fields are part of libhts.so's ABI (hence these fields must not be moved):
   237  //  - fp is used in the public sam_itr_next()/etc macros
   238  //  - is_bin is used directly in samtools <= 1.1 and bcftools <= 1.1
   239  //  - is_write and is_cram are used directly in samtools <= 1.1
   240  //  - fp is used directly in samtools (up to and including current develop)
   241  //  - line is used directly in bcftools (up to and including current develop)
   242  //  - is_bgzf and is_cram flags indicate which fp union member to use.
   243  //    Note is_bgzf being set does not indicate the flag is BGZF compressed,
   244  //    nor even whether it is compressed at all (eg on naked BAMs).
   245  typedef struct htsFile {
   246      uint32_t is_bin:1, is_write:1, is_be:1, is_cram:1, is_bgzf:1, dummy:27;
   247      int64_t lineno;
