   705  // Fix bad records where qname is not terminated correctly.
   706  static int fixup_missing_qname_nul(bam1_t *b) {
   707      bam1_core_t *c = &b->core;
   708
   709      // Note this is called before c->l_extranul is added to c->l_qname
   710      if (c->l_extranul > 0) {
   711          b->data[c->l_qname++] = '\0';
   712          c->l_extranul--;
   713      } else {
   714          if (b->l_data > INT_MAX - 4) return -1;
   715          if (realloc_bam_data(b, b->l_data + 4) < 0) return -1;
   716          b->l_data += 4;
   717          b->data[c->l_qname++] = '\0';
   718          c->l_extranul = 3;
   719      }
   720      return 0;
